type ProductForm = { name: string; price: string; sku: string };

function EditProduct({ initial }: { initial: ProductForm }) {
  const [values, setValues] = useState(initial);
  const [touched, setTouched] = useState<Set<keyof ProductForm>>(new Set());

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const field = e.target.name as keyof ProductForm;
    setValues((v) => ({ ...v, [field]: e.target.value }));
  }

  // Derived, not stored: nothing can get out of sync.
  const isDirty = (Object.keys(initial) as (keyof ProductForm)[]).some((k) => values[k] !== initial[k]);

  return (
    <form>
      <input name="name" value={values.name} onChange={handleChange}
        onBlur={() => setTouched((t) => new Set(t).add("name"))} />
      <button type="button" onClick={() => setValues(initial)} disabled={!isDirty}>Reset</button>
    </form>
  );
}
